#define main pairing_antecedent_main
#include "../cm8-61-pairing-20261115/pairing.cpp"
#undef main
using Poly=std::vector<F>;
void trim(Poly&a){while(!a.empty()&&a.back()==F())a.pop_back();}
int deg(const Poly&a){return int(a.size())-1;}
Poly scale(Poly a,F b){for(auto&x:a)x=x*b;trim(a);return a;}
Poly sub(Poly a,const Poly&b){a.resize(std::max(a.size(),b.size()));for(size_t i=0;i<b.size();i++)a[i]=a[i]-b[i];trim(a);return a;}
struct Unknown{};
int peak;
void bound(int n,int cap){if(n>cap)throw Unknown{};peak=std::max(peak,n);}
Poly product(const Poly&a,const Poly&b,int cap,int weight=0){if(a.empty()||b.empty())return {};bound(deg(a)+deg(b)+weight,cap);Poly c(a.size()+b.size()-1);for(size_t i=0;i<a.size();i++)for(size_t j=0;j<b.size();j++)c[i+j]=c[i+j]+a[i]*b[j];trim(c);return c;}
std::pair<Poly,Poly> divide(Poly a,const Poly&b,int cap){need(!b.empty(),"zero divisor");Poly q;if(deg(a)>=deg(b))q.resize(deg(a)-deg(b)+1);while(!a.empty()&&deg(a)>=deg(b)){int k=deg(a)-deg(b);F v=a.back()/b.back();q[k]=q[k]+v;Poly mono(k+1);mono[k]=v;a=sub(a,product(mono,b,cap));}trim(q);return{q,a};}
struct Cert{Poly f,h,d,u,v;};
Cert certify(const std::vector<F>&a,const std::vector<F>&b,F z,int cap){bound(3,cap);Poly f{F(1)},h{F(1)};for(auto x:a)f=product(f,Poly{F()-x,F(1)},cap);for(auto x:b)h=product(h,Poly{z,F()-x},cap);Poly r0=f,r1=h,u0{F(1)},u1,v0,v1{F(1)};while(!r1.empty()){auto[q,r]=divide(r0,r1,cap);Poly u=sub(u0,product(q,u1,cap,3)),v=sub(v0,product(q,v1,cap,3));r0=r1;r1=r;u0=u1;u1=u;v0=v1;v1=v;}F k=F(1)/r0.back();r0=scale(r0,k);u0=scale(u0,k);v0=scale(v0,k);need(sub(sub(product(u0,f,cap),scale(product(v0,h,cap),F()-F(1))),r0).empty(),"Bezout identity");need(divide(f,r0,cap).second.empty()&&divide(h,r0,cap).second.empty(),"gcd divisibility");return{f,h,r0,u0,v0};}
F eval(const Poly&a,F x){F z;for(size_t i=a.size();i-->0;)z=z*x+a[i];return z;}
std::string poly(const Poly&a){std::ostringstream o;o<<a.size();for(F x:a)o<<','<<encode(x);return o.str();}
using Row=std::array<int,3>;
int rel(int n){n%=31;return n<0?n+31:n;}int rinv(int n){for(int k=1;k<31;k++)if(rel(k*n)==1)return k;throw std::runtime_error("zero relation inverse");}
struct Matrix{std::map<int,std::array<int,4>>a;void insert(Row v,int m){std::array<int,4>r{rel(v[0]),rel(v[1]),rel(v[2]),rel(m)};for(auto&[p,b]:a){int c=r[p];for(int j=0;j<4;j++)r[j]=rel(r[j]-c*b[j]);}int p=0;while(p<3&&!r[p])p++;if(p==3){need(!r[3],"inconsistent setup");return;}int k=rinv(r[p]);for(int&x:r)x=rel(x*k);for(auto&[q,b]:a){int c=b[p];for(int j=0;j<4;j++)b[j]=rel(b[j]-c*r[j]);}a[p]=r;}std::array<int,3>logs(){need(a.size()==3,"incomplete setup");return{a.at(0)[3],a.at(1)[3],a.at(2)[3]};}};
struct Counts{int base_pairs=0,query_pairs=0,branches=0,unknown=0,certified=0,root_checks=0,rows=0,setup_queries=0,online_queries=0,peak=0;};
std::vector<Row> query(P q,P partner,const std::vector<P>&base,const std::vector<F>&images,int cap,Counts&count,std::ostringstream&trace){std::vector<Row>rows;F z;if(cap>=3){auto v=pairing(q,partner);need(v.has_value(),"actual query pairing");z=*v;count.query_pairs++;}trace<<"QUERY "<<(q.o?-1:encode(q.x))<<' '<<(q.o?-1:encode(q.y));trace<<' '<<encode(z)<<'\n';for(int sign:{-1,1})for(int sign2:{-1,1}){count.branches++;peak=0;trace<<"BR "<<sign<<' '<<sign2<<' ';try{bound(3,cap);std::vector<F>a,b;for(F x:images){a.push_back(sign==1?x:inverse(x));b.push_back(sign2==1?x:inverse(x));}Cert c=certify(a,b,z,cap);std::vector<std::pair<int,int>>found;for(int i=0;i<3;i++){count.root_checks++;if(eval(c.d,a[i])==F())for(int j=0;j<3;j++)if(a[i]*b[j]==z){need(add(sign==1?base[i]:neg(base[i]),sign2==1?base[j]:neg(base[j]))==q,"actual source row");Row row{};row[i]+=sign;row[j]+=sign2;rows.push_back(row);found.push_back({i,j});}}trace<<"C "<<peak<<' '<<poly(c.f)<<' '<<poly(c.h)<<' '<<poly(c.d)<<' '<<poly(c.u)<<' '<<poly(c.v)<<' '<<found.size();for(auto[i,j]:found)trace<<' '<<i<<','<<j;trace<<'\n';count.certified++;count.rows+=found.size();}catch(const Unknown&){trace<<"U "<<peak<<'\n';count.unknown++;}count.peak=std::max(count.peak,peak);}return rows;}
void emit(P p,std::ostringstream&t){t<<(p.o?-1:encode(p.x))<<' '<<(p.o?-1:encode(p.y));}
struct Recovery{int scalar=-1,kind=0,rank=0,setup_m=0,shift=-1;std::array<int,3>logs{-1,-1,-1};Counts count;std::string trace;};
Recovery recover_cold(P unknown,P generator,P partner,const std::vector<P>&base,int cap){Recovery out;std::ostringstream trace;std::vector<F>images;if(cap>=3)for(P p:base){auto v=pairing(p,partner);need(v&&*v!=F(1),"public base pairing");images.push_back(*v);out.count.base_pairs++;}Matrix matrix;P setup;
for(int m=1;m<=30&&matrix.a.size()<3;m++){setup=add(setup,generator);out.count.setup_queries++;trace<<"PUBLIC "<<m<<'\n';auto rows=query(setup,partner,base,images,cap,out.count,trace);for(auto row:rows)matrix.insert(row,m);out.setup_m=m;}
out.rank=matrix.a.size();if(out.rank!=3){out.trace=trace.str();return out;}out.logs=matrix.logs();for(int i=0;i<3;i++)need(mul(generator,out.logs[i])==base[i],"legitimate public log");P shifted=unknown;
for(int shift=0;shift<=30;shift++){out.count.online_queries++;trace<<"ONLINE "<<shift<<'\n';if(shifted.o){out.scalar=rel(-shift);out.kind=2;out.shift=shift;trace<<"IDENTITY\n";break;}auto rows=query(shifted,partner,base,images,cap,out.count,trace);if(!rows.empty()){int k=-shift;for(int i=0;i<3;i++)k+=rows[0][i]*out.logs[i];out.scalar=rel(k);out.kind=1;out.shift=shift;break;}shifted=add(shifted,generator);}
need(out.scalar>=0&&mul(generator,out.scalar)==unknown,"original source scalar");out.trace=trace.str();return out;}
int main(int argc,char**argv){try{if(argc==5&&std::string(argv[1])=="mutate"){std::ifstream in(argv[2]);need(bool(in),"input");std::vector<std::vector<std::string>>ls;std::string line;while(std::getline(in,line)){std::istringstream row(line);std::vector<std::string>v;std::string x;while(row>>x)v.push_back(x);ls.push_back(v);}auto old=ls;std::string mode=argv[4];bool done=false;if(mode=="source"){ls[0][1]="60";done=true;}else if(mode=="degree"){ls.back()[1]="0";done=true;}else for(size_t i=0;i<ls.size();i++){auto&v=ls[i];if(mode=="missing-target"&&v[0]=="WORK"){size_t j=i;while(j<ls.size()&&ls[j][0]!="END")j++;need(j<ls.size(),"workload boundary");ls.erase(ls.begin()+i,ls.begin()+j+1);done=true;break;}if(mode=="missing-failure"&&v[0]=="BR"&&v[3]=="U"){ls.erase(ls.begin()+i);done=true;break;}if(v[0]=="WORK"){if(mode=="setup-free"&&v[20]!="0"){v[20]="0";done=true;break;}if(mode=="miller-cost"&&v[14]!="0"){v[14]="0";done=true;break;}if(v[5]=="0")continue;if(mode=="setup-log"){v[10]=std::to_string((std::stoi(v[10])+1)%31);done=true;break;}if(mode=="scalar"){v[6]="0";done=true;break;}if(mode=="rank"){v[7]="2";done=true;break;}if(mode=="online-kind"&&v[5]=="1"){v[5]="2";done=true;break;}}if(v[0]=="BR"&&v[3]=="C"){if(mode=="certificate"&&v[8]!="1,1"){v[8]="1,1";done=true;break;}if(mode=="root"&&v[7]!="1,1"){v[7]="1,1";done=true;break;}}}need(done&&ls!=old,"no semantic mutation");std::ifstream prior(argv[3]);need(!prior.good(),"fresh output");std::ofstream out(argv[3]);for(auto&v:ls){for(size_t i=0;i<v.size();i++){if(i)out<<' ';out<<v[i];}out<<'\n';}return 0;}need(argc==1,"no arguments or mutate INPUT NEW MODE");P g{F(0),F(10),false},partner=chi(P{F(37),F(14),false});auto source=group(g,21,39);std::vector<P>base;for(P q:source)if(!q.o&&std::pair(encode(q.x),encode(q.y))<std::pair(encode(neg(q).x),encode(neg(q).y)))base.push_back(q);base.resize(3);std::cout<<"COLDFIELD 61 59 31 1 9 30\nBASE";for(P p:base){std::cout<<' ';point(p);}std::cout<<'\n';int attempted=0,blocked=0,algebraic=0,identity=0,maxpeak=0;for(int cap=0;cap<=8;cap++)for(int qi=1;qi<31;qi++){P unknown=source[qi];auto r=recover_cold(unknown,g,partner,base,cap);attempted++;blocked+=r.kind==0;algebraic+=r.kind==1;identity+=r.kind==2;maxpeak=std::max(maxpeak,r.count.peak);std::cout<<"WORK "<<cap<<' '<<qi<<' ';point(unknown);std::cout<<' '<<r.kind<<' '<<r.scalar<<' '<<r.rank<<' '<<r.setup_m<<' '<<r.shift;for(int x:r.logs)std::cout<<' '<<x;auto c=r.count;std::cout<<' '<<c.base_pairs<<' '<<c.query_pairs<<' '<<c.branches<<' '<<c.unknown<<' '<<c.certified<<' '<<c.root_checks<<' '<<c.rows<<' '<<c.setup_queries<<' '<<c.online_queries<<' '<<c.peak<<'\n'<<r.trace<<"END\n";}std::cout<<"CHECK "<<attempted<<' '<<blocked<<' '<<algebraic<<' '<<identity<<' '<<maxpeak<<"\nMATRIX NA\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 101;}}
